class Solution {
public:
    long long calculateScore(string s) {
        vector<vector<int>> stacks(26);
        long long totalScore = 0;

        for (int i = 0; i < (int)s.length(); ++i) {
            int chIdx = s[i] - 'a';
            int mirrorIdx = 25 - chIdx;
            if (!stacks[mirrorIdx].empty()) {
                int j = stacks[mirrorIdx].back();
                stacks[mirrorIdx].pop_back();
                totalScore += (i - j);
            } else {
                stacks[chIdx].push_back(i);
            }
        }
        return totalScore;
    }
};

class Solution {
    public long calculateScore(String s) {
        List<Integer>[] stacks = new ArrayList[26];
        for (int i = 0; i < 26; ++i) stacks[i] = new ArrayList<>();
        long totalScore = 0;

        for (int i = 0; i < s.length(); ++i) {
            int chIdx = s.charAt(i) - 'a';
            int mirrorIdx = 25 - chIdx;
            if (!stacks[mirrorIdx].isEmpty()) {
                int j = stacks[mirrorIdx].remove(stacks[mirrorIdx].size() - 1);
                totalScore += (i - j);
            } else {
                stacks[chIdx].add(i);
            }
        }
        return totalScore;
    }
}

var calculateScore = function(s) {
    const stacks = Array.from({ length: 26 }, () => []);
    let totalScore = 0;

    for (let i = 0; i < s.length; ++i) {
        const chIdx = s.charCodeAt(i) - 97;
        const mirrorIdx = 25 - chIdx;
        if (stacks[mirrorIdx].length > 0) {
            const j = stacks[mirrorIdx].pop();
            totalScore += (i - j);
        } else {
            stacks[chIdx].push(i);
        }
    }
    return totalScore;
};
